#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Definitions;
using PVZEngine;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.miracleMalletReplica)]
    public class MiracleMalletReplica : ArtifactDefinition
    {
        public MiracleMalletReplica(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostAdd(Artifact artifact)
        {
            base.PostAdd(artifact);
            if (MinionExists(artifact))
            {
                RemoveMinion(artifact);
            }
            SpawnMinion(artifact);
        }
        public override void PostRemove(Artifact artifact)
        {
            base.PostRemove(artifact);
            RemoveMinion(artifact);
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);
            if (!MinionExists(artifact))
            {
                SpawnMinion(artifact);
            }
        }
        public static bool MinionExists(Artifact artifact)
        {
            var minionID = GetMinionID(artifact);
            return minionID != null && minionID.Exists(artifact.Level);
        }
        public static void SpawnMinion(Artifact artifact)
        {
            var level = artifact.Level;
            var pos = level.GetLawnCenter();
            var source = new ArtifactSourceReference(artifact);
            var minion = level.SpawnSourced(VanillaEffectID.miracleMalletMinion, pos, source);
            if (minion != null)
            {
                var minionID = new EntityID(minion);

                var param = minion.GetSpawnParams();
                param.SetProperty(EngineEntityProps.SIZE, minion.GetSize());
                level.Spawn(VanillaEffectID.smoke, minion.Position, minion, param);

                SetMinionID(artifact, minionID);
            }
        }
        public static void RemoveMinion(Artifact artifact)
        {
            var level = artifact.Level;
            var minionID = GetMinionID(artifact);
            var minion = minionID?.GetEntity(level);
            if (minion != null && minion.Exists())
            {
                var param = minion.GetSpawnParams();
                param.SetProperty(EngineEntityProps.SIZE, minion.GetSize());
                level.Spawn(VanillaEffectID.smoke, minion.Position, minion, param);

                minion.Remove();
            }
        }
        public static EntityID? GetMinionID(Artifact artifact) => artifact.GetProperty<EntityID>(PROP_MINION_ID);
        public static void SetMinionID(Artifact artifact, EntityID? value) => artifact.SetProperty<EntityID>(PROP_MINION_ID, value);
        public static readonly PropertyMeta<EntityID> PROP_MINION_ID = new VanillaArtifactPropertyMeta<EntityID>("minion_id");
    }
}
